	public Map getparameters()
    {
        if(!parametersMap)
        {
            parametersMap  =  new Map(Types::String, Types::Container);
        }
        return parametersMap;
    }

public void addParameter(str _key, container _value)
{
    if(strScan(_key, '/', 0, 2) > -1)
    {
        _key = '/' + _key;
    }
    this.getparameters().add(_key, _value);
}
